describe('Page Title Update on Navigation', () => {
    beforeEach(() => {
        cy.visit('/'); // Adjust the URL to your application's root
    });

    it('should update the page title when navigating to the About section', () => {
        cy.get('nav').contains('About').click(); // Adjust the selector to match your navigation
        cy.title().should('eq', 'About - Your Application Name'); // Adjust the expected title
    });

    it('should not change the page title when navigating to the same section', () => {
        cy.get('nav').contains('Home').click(); // Navigate to Home
        cy.title().should('eq', 'Home - Your Application Name'); // Adjust the expected title
        cy.get('nav').contains('Home').click(); // Click Home again
        cy.title().should('eq', 'Home - Your Application Name'); // Title should remain the same
    });
});
